export default {
  // 此处编写的是vue组件实例的配置项，通过一定语法，可以直接混入到组件内复用
  // data methods computed 生命周期函数...
  // 注意点：
  // 1：如果此处和组件内，提供了同名的data或methods，则组件内优先级更高
  // 2：如果编写了生命周期函数，则mixins中对的生命周期函数和页面的生命周期函数，会用数组管理
// 执统一行

  methods: {
    loginConfirm () {
      // 判断是否有token
      // token不存在则弹出请求框
      // token存在则继续正常请求
      if (!this.$store.getters.token) {
        this.$dialog.confirm({
          title: '温馨提示',
          message: '需要先登录才能继续操作哦'
        })
          .then(() => {
            // 跳转到登录页，然后回弹到原来的页面--需要在跳转去携带参数（当前的路径地址）
            // this.$route.fullPath(会包含查询参数)
            this.$router.replace({
              path: '/login',
              query:
              {
                backUrl: this.$route.fullPath
              }
            })
          })
          .catch(() => {
          })
        return true
      }
      return false
    }
  }

}
